import json, subprocess, warnings
warnings.filterwarnings("ignore")
from TTS.utils.synthesizer import Synthesizer
from hts_close import close_voice
lines = [
 "हाथ पैरों में झुनझुनी? सुन्नपन? या मांसपेशियों में कमज़ोरी? ऐसे में डॉक्टर ई एम जी और एन सी वी टेस्ट लिख सकते हैं. यह टेस्ट क्या है, और कैसे होता है? आखिर तक देखिए.",
 "हमारी नसें, दिमाग से मांसपेशियों तक, बिजली जैसे संदेश ले जाती हैं. ई एम जी, यानी इलेक्ट्रोमायोग्राफी, मांसपेशियों की बिजली की गतिविधि रिकॉर्ड करता है. और एन सी वी, यानी नर्व कंडक्शन स्टडी, देखता है कि नस में संदेश कितनी तेज़ी और ताकत से चलता है.",
 "यह टेस्ट कब लिखा जाता है? हाथ, पैर या चेहरे में झुनझुनी या सुन्नपन, मांसपेशियों में कमज़ोरी, ऐंठन या फड़कन, या किसी हिस्से में लकवा.",
 "यह कई बीमारियों की पहचान में मदद करता है. जैसे कार्पल टनल सिंड्रोम, यानी कलाई में नस दबना. नसों की बीमारी, यानी न्यूरोपैथी, जो डायबिटीज़ में आम है. रीढ़ की डिस्क से नस दबना. मायस्थीनिया ग्रेविस, और मांसपेशियों की कुछ बीमारियां.",
 "पहले आमतौर पर एन सी वी होता है. त्वचा पर स्टिकर जैसे इलेक्ट्रोड लगाए जाते हैं, और बहुत हल्का बिजली का झटका दिया जाता है. कुछ सेकंड के लिए हल्की झनझनाहट महसूस होती है.",
 "फिर ई एम जी. एक बहुत पतली सुई मांसपेशी में लगाई जाती है. आपको मांसपेशी ढीली रखने, और फिर हल्के से कसने को कहा जाता है. सुई से थोड़ा दर्द हो सकता है, जो सुई निकलने के बाद जल्दी ठीक हो जाता है. ज़्यादा दर्द हो, तो बताइए.",
 "तैयारी कैसे करें? टेस्ट से पहले नहा लें. त्वचा पर क्रीम, लोशन या तेल न लगाएं. ढीले कपड़े पहनें. आमतौर पर खाली पेट आने की ज़रूरत नहीं होती.",
 "डॉक्टर को ज़रूर बताएं, अगर आपको पेसमेकर लगा है, या आप खून पतला करने की दवा लेते हैं. कोई भी दवा अपने आप बंद न करें, डॉक्टर से पूछें.",
 "पूरा टेस्ट आमतौर पर आधे घंटे से डेढ़ घंटे तक का होता है. यह इस पर निर्भर है कि कितनी नसें और मांसपेशियां जांची जा रही हैं. बाद में एक दो दिन हल्का दर्द या नील पड़ सकता है. रिपोर्ट न्यूरोलॉजिस्ट बनाते हैं, और आपके डॉक्टर उसे लक्षणों के साथ समझते हैं.",
 close_voice("क्या आपके हाथ पैरों में कभी झुनझुनी होती है?"),
]
import os
d = os.environ.get("HTS_MODEL", "/tmp/hi/hi/")
s = Synthesizer(tts_checkpoint=d + "fastpitch/best_model.pth", tts_config_path=d + "fastpitch/config.json",
                vocoder_checkpoint=d + "hifigan/best_model.pth", vocoder_config=d + "hifigan/config.json", use_cuda=False)
durs = []
for i, l in enumerate(lines):
    f = f"/tmp/emgr_{i}.wav"; s.save_wav(s.tts(l, speaker_name="female"), f)
    subprocess.run(["ffmpeg","-nostdin","-y","-loglevel","error","-i",f,"-af","rubberband=pitch=0.96:formant=preserved,equalizer=f=250:t=q:w=1:g=2,treble=g=-1.5:f=6000",f"/tmp/emg_{i}.wav"],check=True); f=f"/tmp/emg_{i}.wav"
    durs.append(float(subprocess.check_output(["ffprobe", "-v", "error", "-show_entries", "format=duration", "-of", "csv=p=0", f]).decode()))
json.dump(durs, open("/tmp/emg_durs.json", "w")); print([round(x, 1) for x in durs], round(sum(durs), 1))
